package android.app;import android.content.*;import java.util.*;public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=4;static final Map<String,PendingIntent> all=new HashMap<>();public Intent intent;public int flags;public static PendingIntent getBroadcast(Context c,int code,Intent i,int f){String key=code+":"+i.target+":"+i.action;PendingIntent p=all.computeIfAbsent(key,k->new PendingIntent());p.intent=i;p.flags=f;return p;}}
